<script>
document.addEventListener('DOMContentLoaded',()=>{
const state={currentView:'home',sessions:{},activeSessionId:null};
const views={home:document.getElementById('view-home'),app:document.getElementById('view-app')};
const goToAppBtn=document.getElementById('go-to-app-btn');
const backToHomeBtn=document.getElementById('back-to-home-btn');
const settingsBtn=document.getElementById('settings-btn');
const closeSettingsBtn=document.getElementById('close-settings-btn');
const settingsModal=document.getElementById('settings-modal');
const themeToggleButton=document.getElementById('theme-toggle');
const chatForm=document.getElementById('chat-form');
const chatInput=document.getElementById('chat-input');
const chatTitle=document.getElementById('chat-title');
const messageList=document.getElementById('message-list');
const sessionList=document.getElementById('session-list');
const contextContent=document.getElementById('context-content');
function switchView(viewName){
if(!views[viewName]||state.currentView===viewName)return;
views[state.currentView].classList.add('hidden');
views[viewName].classList.remove('hidden');
state.currentView=viewName;
if(viewName==='app'&&!state.activeSessionId){createNewSession('Új Beszélgetés')}
}
function createNewSession(title){
const sessionId=`sid_${Date.now()}`;
state.sessions[sessionId]={title,messages:[],status:'active'};
setActiveSession(sessionId);
addMessage(sessionId,'bot','Üdvözlöm! Miben segíthetek? Indítson kutatást a `!research` paranccsal, vagy tegyen fel egy kérdést.');
renderSessionList()
}
function setActiveSession(sessionId){
state.activeSessionId=sessionId;
const session=state.sessions[sessionId];
chatTitle.textContent=session.title;
messageList.innerHTML='';
session.messages.forEach(msg=>addMessage(sessionId,msg.sender,msg.content,msg.type,false));
renderSessionList()
}
function renderSessionList(){
sessionList.innerHTML='';
Object.entries(state.sessions).forEach(([id,session])=>{
const btn=document.createElement('button');
btn.className='w-full text-left px-3 py-2 rounded-lg font-semibold text-sm truncate';
btn.style.color='var(--ts-on-dark)';
btn.textContent=session.title;
if(id===state.activeSessionId){
btn.style.backgroundColor='rgba(255,210,122,.15)';
btn.classList.add('active')
}
btn.onclick=()=>setActiveSession(id);
sessionList.prepend(btn)
})
}
function addMessage(sessionId,sender,content,type='html',save=true){
if(save){state.sessions[sessionId].messages.push({sender,content,type})}
if(sessionId!==state.activeSessionId)return;
const messageTemplate=document.getElementById('message-template');
const messageEl=messageTemplate.content.cloneNode(true).firstElementChild;
const bubble=messageEl.querySelector('.chat-bubble');
const contentDiv=messageEl.querySelector('.message-content');
messageEl.classList.add(sender==='user'?'justify-end':'justify-start','fade-in-up');
bubble.classList.add(sender==='user'?'chat-bubble-user':'chat-bubble-bot');
if(type==='loading'){
const loaderTemplate=document.getElementById('loader-template');
contentDiv.appendChild(loaderTemplate.content.cloneNode(true))
}else{
contentDiv.innerHTML=content
}
messageList.appendChild(messageEl);
messageList.parentElement.scrollTop=messageList.parentElement.scrollHeight;
return messageEl
}
async function handleChatSubmit(e){
e.preventDefault();
const userInput=chatInput.value.trim();
if(!userInput||!state.activeSessionId)return;
const currentSessionId=state.activeSessionId;
addMessage(currentSessionId,'user',userInput);
chatInput.value='';
chatInput.style.height='auto';
const{command,query}=parseUserInput(userInput);
if(command==='!research'){
state.sessions[currentSessionId].title=query.length>25?query.substring(0,22)+'...':query;
renderSessionList();
await backendSimulator.research(currentSessionId,query)
}else{
const loadingMessage=addMessage(currentSessionId,'bot','','loading');
const response=await backendSimulator.chat({query});
loadingMessage.remove();
addMessage(currentSessionId,'bot',marked.parse(response.reply))
}
}
function parseUserInput(input){
const parts=input.split(/\s+/);
const command=parts[0].toLowerCase();
if(command==='!research'){
return{command,query:parts.slice(1).join(' ')}
}
return{command:'chat',query:input}
}
const backendSimulator={
async research(sessionId,query){
contextContent.innerHTML='';
const updateStatus=(action,progress)=>{
const statusHtml=`<div class="p-2 fade-in-up"><strong>Folyamatban:</strong><p class="text-sm mt-2">${action}</p><div class="w-full h-2 rounded-full mt-2" style="background-color:rgba(255,255,255,.1)"><div class="h-2 rounded-full" style="width:${progress}%;background:linear-gradient(90deg,var(--ts-pink),var(--ts-gold-1));transition:width .5s ease"></div></div></div>`;
contextContent.innerHTML=statusHtml
};
const sleep=ms=>new Promise(res=>setTimeout(res,ms));
updateStatus('Hipotézisek generálása',10);
await sleep(1500);
const hypotheses=Array.from({length:5},(_,i)=>`Hipotézis ${i+1}: ${query} más szemszögből.`);
addMessage(sessionId,'bot',`**Generált hipotézisek:**\n- ${hypotheses.join('\n- ')}`);
updateStatus('Párhuzamos forráskeresés',30);
await sleep(2000);
const sources=Array.from({length:5},(_,i)=>({
url:``,
title:`Releváns Forrás ${i+1} a kutatáshoz`,
text:'Ez a forrás részletesen tárgyalja a témát, különös tekintettel a legújabb fejleményekre.'
}));
addMessage(sessionId,'bot',`**Legjobb 5 forrás megtalálva:**\n${sources.map(s=>`[${s.title}](${s.url})`).join('\n')}`);
updateStatus('Több-modelles szintézis',70);
await sleep(2500);
updateStatus('Kritika és revízió',90);
await sleep(1500);
updateStatus('Jelentés elkészült',100);
const report=`# Kutatási Jelentés\n\n### Téma: ${query}\n\nEz egy MI által generált, részletes összefoglaló, amely több forrás és nézőpont szintézisével jött létre.\n\n**Főbb megállapítások:**\n1. **Első pont:** A kutatás megerősítette, hogy a szimulált adatok alapján a téma relevanciája magas.\n2. **Második pont:** A gazdasági és társadalmi hatások jelentősek lehetnek a következő évtizedben.\n\n*A teljes jelentés letölthető lenne egy valós rendszerben.*`;
addMessage(sessionId,'bot',marked.parse(report))
},
async chat({query}){
await new Promise(res=>setTimeout(res,800+Math.random()*1000));
return{reply:`A "${query}" kérdésre a válaszom, hogy ez egy komplex téma. A szimulált tudásbázisom alapján a legfontosabb szempontok a következők...`}
}
};
goToAppBtn.addEventListener('click',()=>switchView('app'));
backToHomeBtn.addEventListener('click',(e)=>{e.preventDefault();switchView('home')});
settingsBtn.addEventListener('click',()=>settingsModal.classList.remove('hidden'));
closeSettingsBtn.addEventListener('click',()=>settingsModal.classList.add('hidden'));
themeToggleButton.addEventListener('click',()=>alert('A Tiffy Time stílus fix beállítás!'));
chatForm.addEventListener('submit',handleChatSubmit);
chatInput.addEventListener('input',()=>{chatInput.style.height='auto';chatInput.style.height=`${Math.min(chatInput.scrollHeight,200)}px`});
chatInput.addEventListener('keydown',(e)=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();chatForm.requestSubmit()}});
switchView('home')
});
</script>
